// Library workflow: fetch Vapi call records and extract the fields every report
// uses, written once. Callers (WF-20/21/22) pass { sinceIso, untilIso, limit } and
// read back ONE item holding { calls: [...] } — a single item rather than one item
// per call, so a quiet window still flows through the caller's summarise node and
// the zero-row guarantee survives (a missing report is ambiguous; a zero row is not).
// Semantics preserved exactly from the three reports this replaces: booked /
// escalated / medicalHold are strict === true checks on Vapi's structured outcome.
const raw = $input.all().map(i => i.json).flat().filter(c => c && c.id);
const calls = raw.map(c => {
  const o = (c.analysis && c.analysis.structuredData) || {};
  return {
    id: c.id,
    startedAt: c.startedAt || '',
    durationSeconds: c.startedAt && c.endedAt
      ? (new Date(c.endedAt) - new Date(c.startedAt)) / 1000 : 0,
    endedReason: String(c.endedReason || ''),
    booked: o.booked === true,
    escalated: o.escalated === true,
    medicalHold: o.medicalHold === true,
    intent: o.intent || 'unknown',
    recordingUrl: (c.artifact && c.artifact.recordingUrl) || '',
  };
});
return [{ json: { calls } }];
